171	
172	    /**
173	     * Return the initials of this owner, being the first letter of the first and
174	     * last name, upper-cased and dot-separated with a trailing dot, e.g. 'J.S.'.
175	     *
176	     * @return the formatted initials
177	     */
178	    @Transient
179	    public String getInitials() {
180	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
181	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
182	    }
183	
184	    @Override
185	    public String toString() {
186	        return new ToStringCreator(this)
187	
188	            .append("id", this.getId())
189	            .append("new", this.isNew())
190	            .append("lastName", this.getLastName())
